module LatinSquareSolver (\n    input clk,\n    input rst_n,\n    input start,\n    input [1:0] k,\n    input [3:0] in_row0_0, in_row0_1, in_row0_2, in_row0_3,\n    input [3:0] in_row1_0, in_row1_1, in_row1_2, in_row1_3,\n    input [3:0] in_row2_0, in_row2_1, in_row2_2, in_row2_3,\n    input [3:0] in_row3_0, in_row3_1, in_row3_2, in_row3_3,\n    output reg done,\n    output reg yes,\n    output reg [3:0] result_0_0, result_0_1, result_0_2, result_0_3,\n    output reg [3:0] result_1_0, result_1_1, result_1_2, result_1_3,\n    output reg [3:0] result_2_0, result_2_1, result_2_2, result_2_3,\n    output reg [3:0] result_3_0, result_3_1, result_3_2, result_3_3\n);\n\n    // State definitions\n    localparam [2:0] IDLE            = 3'd0;\n    localparam [2:0] VALIDATE_ROW    = 3'd1;\n    localparam [2:0] VALIDATE_COL    = 3'd2;\n    localparam [2:0] FIND_EMPTY      = 3'd3;\n    localparam [2:0] TRY_PLACE       = 3'd4;\n    localparam [2:0] CHECK_VALID     = 3'd5;\n    localparam [2:0] BACKTRACK       = 3'd6;\n    localparam [2:0] DONE_STATE      = 3'd7;\n\n    reg [2:0] current_state, next_state;\n    reg [3:0] grid [0:3][0:3];     // Current grid state\n    reg [2:0] next_try [0:3][0:3]; // Track next number to try (1-4), 5=completed\n    reg [1:0] row_ptr, col_ptr;    // Current cell being filled\n    reg [2:0] check_row, check_col;\n    reg [1:0] backtrack_row, backtrack_col;\n    reg [3:0] check_val;\n    reg valid_flag;\n    reg [7:0] cycle_counter;\n    integer i, j;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Initialize all registers\n            done <= 1'b0;\n            yes <= 1'b0;\n            current_state <= IDLE;\n            \n            for (i = 0; i < 4; i = i+1) begin\n                for (j = 0; j < 4; j = j+1) begin\n                    grid[i][j] <= 4'd0;\n                    next_try[i][j] <= 3'd0;\n                end\n            end\n            \n            // Clear result outputs\n            {result_0_0, result_0_1, result_0_2, result_0_3} <= '{4{4'd0}};\n            {result_1_0, result_1_1, result_1_2, result_1_3} <= '{4{4'd0}};\n            {result_2_0, result_2_1, result_2_2, result_2_3} <= '{4{4'd0}};\n            {result_3_0, result_3_1, result_3_2, result_3_3} <= '{4{4'd0}};\n            \n            row_ptr <= 2'd0;\n            col_ptr <= 2'd0;\n            cycle_counter <= 8'd0;\n        end\n        else begin\n            case (current_state)\n                IDLE: begin\n                    done <= 1'b0;\n                    cycle_counter <= 8'd0;\n                    if (start) begin\n                        // Load input grid\n                        grid[0][0] <= in_row0_0;\n                        grid[0][1] <= in_row0_1;\n                        grid[0][2] <= in_row0_2;\n                        grid[0][3] <= in_row0_3;\n                        grid[1][0] <= in_row1_0;\n                        grid[1][1] <= in_row1_1;\n                        grid[1][2] <= in_row1_2;\n                        grid[1][3] <= in_row1_3;\n                        grid[2][0] <= in_row2_0;\n                        grid[2][1] <= in_row2_1;\n                        grid[2][2] <= in_row2_2;\n                        grid[2][3] <= in_row2_3;\n                        grid[3][0] <= in_row3_0;\n                        grid[3][1] <= in_row3_1;\n                        grid[3][2] <= in_row3_2;\n                        grid[3][3] <= in_row3_3;\n                        \n                        // Initialize next_try\n                        for (i = 0; i < 4; i = i+1) begin\n                            for (j = 0; j < 4; j = j+1) begin\n                                if (i < k) next_try[i][j] <= 3'd5;\n                                else next_try[i][j] <= 3'd1;\n                            end\n                        end\n                        \n                        current_state <= VALIDATE_ROW;\n                        check_row <= 3'd0;\n                    end\n                end\n                \n                VALIDATE_ROW: begin\n                    // Validate pre-filled rows (0 to k-1)\n                    if (check_row < k) begin\n                        // Check numbers are 1-4\n                        if (grid[check_row][0] < 4'd1 || grid[check_row][0] > 4'd4 ||\n                            grid[check_row][1] < 4'd1 || grid[check_row][1] > 4'd4 ||\n                            grid[check_row][2] < 4'd1 || grid[check_row][2] > 4'd4 ||\n                            grid[check_row][3] < 4'd1 || grid[check_row][3] > 4'd4) begin\n                            yes <= 1'b0;\n                            current_state <= DONE_STATE;\n                        end\n                        // Check for duplicate values in row\n                        else if (grid[check_row][0] == grid[check_row][1] ||\n                                 grid[check_row][0] == grid[check_row][2] ||\n                                 grid[check_row][0] == grid[check_row][3] ||\n                                 grid[check_row][1] == grid[check_row][2] ||\n                                 grid[check_row][1] == grid[check_row][3] ||\n                                 grid[check_row][2] == grid[check_row][3]) begin\n                            yes <= 1'b0;\n                            current_state <= DONE_STATE;\n                        end\n                        else begin\n                            check_row <= check_row + 3'd1;\n                        end\n                    end\n                    else begin\n                        check_col <= 3'd0;\n                        current_state <= VALIDATE_COL;\n                    end\n                end\n                \n                VALIDATE_COL: begin\n                    // Validate pre-filled columns\n                    if (check_col < 3'd4) begin\n                        // Check values 1-4 in each pre-filled row\n                        for (i = 0; i < k; i = i+1) begin\n                            if (grid[i][check_col] < 4'd1 || grid[i][check_col] > 4'd4) begin\n                                yes <= 1'b0;\n                                current_state <= DONE_STATE;\n                            end\n                        end\n                        // Check duplicates in this column\n                        for (i = 0; i < k; i = i+1) begin\n                            for (j = i+1; j < k; j = j+1) begin\n                                if (grid[i][check_col] == grid[j][check_col]) begin\n                                    yes <= 1'b0;\n                                    current_state <= DONE_STATE;\n                                end\n                            end\n                        end\n                        check_col <= check_col + 3'd1;\n                    end\n                    else begin\n                        // Validation passed\n                        row_ptr <= k;\n                        col_ptr <= 2'd0;\n                        current_state <= FIND_EMPTY;\n                    end\n                end\n                \n                FIND_EMPTY: begin\n                    cycle_counter <= cycle_counter + 8'd1;\n                    // Find next empty cell (starting from current row_ptr/col_ptr)\n                    if (row_ptr[1] || row_ptr >= k) begin  // row_ptr >= k\n                        if (next_try[row_ptr][col_ptr] != 3'd5) begin\n                            current_state <= TRY_PLACE;\n                        end\n                        else begin\n                            // Move to next cell\n                            if (col_ptr == 2'd3) begin\n                                col_ptr <= 2'd0;\n                                row_ptr <= row_ptr + 2'd1;\n                            end\n                            else begin\n                                col_ptr <= col_ptr + 2'd1;\n                            end\n                            \n                            // Check if filled all cells\n                            if (row_ptr == 2'd4) begin  // Completed\n                                yes <= 1'b1;\n                                current_state <= DONE_STATE;\n                            end\n                        end\n                    end\n                    else begin\n                        // Skip pre-filled rows\n                        row_ptr <= k;\n                        col_ptr <= 2'd0;\n                    end\n                end\n                \n                TRY_PLACE: begin\n                    if (next_try[row_ptr][col_ptr] < 3'd5) begin\n                        grid[row_ptr][col_ptr] <= next_try[row_ptr][col_ptr];\n                        check_val <= next_try[row_ptr][col_ptr];\n                        check_row <= 3'd0;\n                        check_col <= 3'd0;\n                        valid_flag <= 1'b1;\n                        current_state <= CHECK_VALID;\n                    end\n                    else begin\n                        // No valid numbers left, backtrack\n                        current_state <= BACKTRACK;\n                    end\n                end\n                \n                CHECK_VALID: begin\n                    // Check current value validity in row and column\n                    if (valid_flag) begin\n                        // Check row\n                        for (j = 0; j < 4; j = j+1) begin\n                            if (j != col_ptr && grid[row_ptr][j] == check_val) begin\n                                valid_flag <= 1'b0;\n                            end\n                        end\n                        // Check column\n                        for (i = 0; i < 4; i = i+1) begin\n                            if (i != row_ptr && grid[i][col_ptr] == check_val) begin\n                                valid_flag <= 1'b0;\n                            end\n                        end\n                        current_state <= TRY_PLACE;\n                    end\n                    else begin\n                        if (next_try[row_ptr][col_ptr] < 3'd4) begin\n                            next_try[row_ptr][col_ptr] <= next_try[row_ptr][col_ptr] + 3'd1;\n                            current_state <= TRY_PLACE;\n                        end\n                        else begin\n                            // Exhausted all possibilities - backtrack\n                            grid[row_ptr][col_ptr] <= 4'd0;\n                            next_try[row_ptr][col_ptr] <= 3'd1;\n                            current_state <= BACKTRACK;\n                        end\n                    end\n                end\n                \n                BACKTRACK: begin\n                    // Move to previous cell\n                    if (col_ptr == 2'd0) begin\n                        col_ptr <= 2'd3;\n                        row_ptr <= row_ptr - 2'd1;\n                    end\n                    else begin\n                        col_ptr <= col_ptr - 2'd1;\n                    end\n                    \n                    // Check if backtracked before first empty cell\n                    if (row_ptr < k) begin\n                        yes <= 1'b0;\n                        current_state <= DONE_STATE;\n                    end\n                    else begin\n                        if (next_try[row_ptr][col_ptr] < 3'd4) begin\n                            next_try[row_ptr][col_ptr] <= next_try[row_ptr][col_ptr] + 3'd1;\n                            current_state <= TRY_PLACE;\n                        end\n                        else begin\n                            grid[row_ptr][col_ptr] <= 4'd0;\n                            next_try[row_ptr][col_ptr] <= 3'd1;\n                            // Continue backtracking\n                            current_state <= BACKTRACK;\n                        end\n                    end\n                end\n                \n                DONE_STATE: begin\n                    done <= 1'b1;\n                    if (yes) begin\n                        // Output filled grid\n                        result_0_0 <= grid[0][0]; result_0_1 <= grid[0][1]; result_0_2 <= grid[0][2]; result_0_3 <= grid[0][3];\n                        result_1_0 <= grid[1][0]; result_1_1 <= grid[1][1]; result_1_2 <= grid[1][2]; result_1_3 <= grid[1][3];\n                        result_2_0 <= grid[2][0]; result_2_1 <= grid[2][1]; result_2_2 <= grid[2][2]; result_2_3 <= grid[2][3];\n                        result_3_0 <= grid[3][0]; result_3_1 <= grid[3][1]; result_3_2 <= grid[3][2]; result_3_3 <= grid[3][3];\n                    end\n                    current_state <= IDLE;\n                end\n                \n                default: current_state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule